$csrf=function_exists('authCsrfToken') ? authCsrfToken() : ($_SESSION['csrf_token'] ?? '');
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Correspondências Sponte • Liceu Brasil</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f5f7fb;color:#172033;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,sans-serif}.top{height:68px;background:linear-gradient(90deg,#0a55a6,#0b63bd);color:#fff;display:flex;align-items:center;padding:0 22px;gap:14px;position:sticky;top:0;z-index:20;box-shadow:0 4px 18px #0f172a1f}.back{border:1px solid #ffffff44;background:#ffffff14;color:#fff;border-radius:9px;padding:9px 12px;text-decoration:none;font-weight:800}.title strong{display:block;font-size:16px}.title span{font-size:12px;opacity:.72}.wrap{max-width:1450px;margin:22px auto;padding:0 18px}.tabs{display:flex;gap:8px;margin-bottom:16px}.tab{border:1px solid #dbe4ef;background:#fff;border-radius:10px;padding:10px 14px;font-weight:800;color:#526078;cursor:pointer}.tab.active{background:#0b63bd;color:#fff;border-color:#0b63bd}.toolbar{display:flex;gap:10px;align-items:end;flex-wrap:wrap;background:#fff;border:1px solid #e4eaf2;border-radius:14px;padding:14px;margin-bottom:14px}.field{display:flex;flex-direction:column;gap:5px}.field label{font-size:11px;text-transform:uppercase;font-weight:900;color:#78859a}.field input,.field select{height:40px;border:1px solid #d9e1eb;border-radius:9px;padding:0 11px;min-width:220px;background:#fff}.stats{display:flex;gap:9px;margin-left:auto}.pill{background:#eef6ff;color:#0a55a6;padding:9px 12px;border-radius:10px;font-size:12px;font-weight:900}.card{background:#fff;border:1px solid #e3e9f1;border-radius:14px;box-shadow:0 3px 13px #0f172a0b;margin-bottom:12px;overflow:hidden}.card-head{padding:15px 16px;display:grid;grid-template-columns:minmax(220px,1.5fr) 1fr 110px 120px auto;gap:14px;align-items:center;border-bottom:1px solid #edf1f6}.name{font-weight:900;color:#172033}.muted{font-size:12px;color:#7a8799;margin-top:3px}.money{font-weight:900}.badge{display:inline-flex;padding:5px 8px;border-radius:999px;background:#eef2ff;color:#4351a5;font-size:11px;font-weight:900}.candidates{padding:12px 16px;background:#fbfcfe}.cand{display:grid;grid-template-columns:70px minmax(220px,1fr) minmax(220px,1fr) auto;gap:12px;align-items:center;padding:10px;border:1px solid #e7ecf2;border-radius:10px;background:#fff;margin:7px 0}.score{font-weight:950;color:#0b63bd;font-size:16px}.reason{font-size:11px;color:#7c8796}.btn{border:0;border-radius:9px;padding:9px 12px;font-weight:850;cursor:pointer}.btn-primary{background:#0b63bd;color:#fff}.btn-soft{background:#edf4fb;color:#0b5ca9}.empty{padding:38px;text-align:center;color:#7a8799;background:#fff;border:1px dashed #ccd6e3;border-radius:14px}.cancel-grid{display:grid;grid-template-columns:1.4fr 1fr 120px 1fr 1.1fr auto;gap:12px;align-items:center;padding:13px 16px}.status-ok{color:#0d8a55;font-weight:900}.status-pend{color:#c47b00;font-weight:900}.motivo{width:100%;height:38px;border:1px solid #d9e1eb;border-radius:8px;padding:0 9px}@media(max-width:900px){.card-head,.cand,.cancel-grid{grid-template-columns:1fr}.stats{margin-left:0}.field input,.field select{min-width:160px}}
</style></head><body>
<div class="top"><a class="back" href="index.php">← Mapa</a><div class="title"><strong>Correspondências Sponte</strong><span>Revisão de pagamentos e histórico de cancelamentos</span></div></div>
<div class="wrap">
<div class="tabs"><button id="tabCorr" class="tab active" onclick="trocar('corr')">Correspondências pendentes</button><button id="tabCan" class="tab" onclick="trocar('can')">Cancelamentos</button></div>
<div class="toolbar"><div class="field"><label>Buscar</label><input id="q" type="search" placeholder="Aluno, curso, contrato..." oninput="render()"></div><div class="field"><label>Categoria</label><select id="cat" onchange="render()"><option value="">Todas</option><option>Mensalidade</option><option>Taxa de Matrícula</option><option>Cancelamento</option></select></div><button class="btn btn-soft" onclick="carregar()">↻ Atualizar</button><div class="stats"><span class="pill" id="stat">0 pendências</span></div></div>
<div id="lista"></div></div>
<script>
const CSRF=<?=json_encode($csrf,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>;let modo='corr',corr=[],cans=[];
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const date=v=>{if(!v)return '—';const p=v.split('-');return p.length===3?`${p[2]}/${p[1]}/${p[0]}`:v};
async function get(action){const r=await fetch(`api.php?action=${action}`,{credentials:'same-origin',cache:'no-store'});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha');return j}
async function post(action,data){const r=await fetch(`api.php?action=${action}`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':CSRF},body:JSON.stringify(data)});const j=await r.json();if(!r.ok||!j.ok)throw new Error(j.error||'Falha');return j}
async function carregar(){document.getElementById('lista').innerHTML='<div class="empty">Carregando...</div>';try{if(modo==='corr'){const j=await get('correspondencias_sponte');corr=j.itens||[]}else{const j=await get('cancelamentos_sponte');cans=j.itens||[]}render()}catch(e){document.getElementById('lista').innerHTML=`<div class="empty">${esc(e.message)}</div>`}}
function trocar(m){modo=m;document.getElementById('tabCorr').classList.toggle('active',m==='corr');document.getElementById('tabCan').classList.toggle('active',m==='can');document.getElementById('cat').style.display=m==='corr'?'block':'none';carregar()}
function render(){const q=(document.getElementById('q').value||'').toLowerCase(),cat=document.getElementById('cat').value;const box=document.getElementById('lista');if(modo==='corr'){const itens=corr.filter(x=>(!cat||x.categoria===cat)&&(!q||`${x.nome} ${x.contrato||''} ${x.turma||''}`.toLowerCase().includes(q)));document.getElementById('stat').textContent=`${itens.length} pendência(s)`;if(!itens.length){box.innerHTML='<div class="empty">Nenhuma correspondência pendente com estes filtros.</div>';return}box.innerHTML=itens.map(item=>`<div class="card"><div class="card-head"><div><div class="name">${esc(item.nome)}</div><div class="muted">${esc(item.turma||'Turma não informada')}</div></div><div><span class="badge">${esc(item.categoria||'Financeiro')}</span><div class="muted">Contrato: ${esc(item.contrato||'—')}</div></div><div class="money">${money(item.valor)}</div><div>${date(item.data)}</div><div class="muted">Lanç. #${item.lancamentoId}</div></div><div class="candidates">${(item.candidatos||[]).length?(item.candidatos||[]).map(c=>`<div class="cand"><div class="score">${Math.min(100,c.score)}%</div><div><div class="name">${esc(c.aluno)}</div><div class="reason">${esc((c.razoes||[]).join(' • '))}</div></div><div><strong>${esc(c.curso||'Sem curso')}</strong><div class="muted">${esc([c.dia,c.horario].filter(Boolean).join(' • ')||'Sem horário')}</div></div><div><button class="btn btn-primary" onclick="vincular(${item.id},${c.alunoId},'${esc(item.nome).replace(/'/g,"\\'")}')">Vincular</button></div></div>`).join(''):'<div class="muted">Nenhum candidato seguro encontrado. Cadastre/corrija o aluno ou aguarde mais dados do relatório.</div>'}</div></div>`).join('')}else{const itens=cans.filter(x=>!q||`${x.nome} ${x.curso||''} ${x.contrato||''} ${x.motivo||''}`.toLowerCase().includes(q));document.getElementById('stat').textContent=`${itens.length} cancelamento(s)`;if(!itens.length){box.innerHTML='<div class="empty">Nenhum cancelamento registrado.</div>';return}box.innerHTML=itens.map(x=>`<div class="card"><div class="cancel-grid"><div><div class="name">${esc(x.nome)}</div><div class="muted">Sponte: ${esc(x.nomeSponte)}</div></div><div><strong>${esc(x.curso||x.turmaSponte||'Matrícula não identificada')}</strong><div class="muted">${esc([x.dia,x.horario].filter(Boolean).join(' • '))}</div></div><div>${date(x.data)}</div><div><span class="${x.statusVinculo==='aplicado'?'status-ok':'status-pend'}">${x.statusVinculo==='aplicado'?'✓ Aplicado':'⚠ Pendente'}</span><div class="muted">${esc(x.metodoVinculo||'')}</div>${x.statusVinculo!=='aplicado'&&(x.matriculasAtivas||[]).length?`<select class="motivo" id="mat-${x.id}" style="margin-top:6px"><option value="">Escolher matrícula...</option>${x.matriculasAtivas.map(m=>`<option value="${m.matriculaId}">${esc(m.curso)} • ${esc([m.dia,m.horario].filter(Boolean).join(' • '))}</option>`).join('')}</select><button class="btn btn-primary" style="margin-top:6px" onclick="aplicarCancel(${x.id})">Aplicar cancelamento</button>`:''}</div><div><input class="motivo" id="mot-${x.id||('m'+x.matriculaId)}" value="${esc(x.motivo||'')}" placeholder="Motivo (opcional)"></div><div><button class="btn btn-soft" onclick="salvarMotivo(${x.id||0},${x.matriculaId||0})">Salvar motivo</button></div></div></div>`).join('')}}
async function vincular(id,alunoId,nome){const todos=confirm(`Vincular este pagamento de ${nome} ao aluno escolhido?\n\nOK = vincular TODOS os pagamentos pendentes com o mesmo nome do XML.\nCancelar = apenas este lançamento.`);try{await post('vincular_correspondencia_sponte',{pagamentoId:id,alunoId,aplicarMesmoNome:todos});await carregar()}catch(e){alert(e.message)}}
async function aplicarCancel(id){const el=document.getElementById(`mat-${id}`);const matriculaId=Number(el&&el.value||0);if(!matriculaId){alert('Escolha a matrícula correta.');return}if(!confirm('Aplicar este cancelamento à matrícula selecionada?'))return;try{await post('aplicar_cancelamento_sponte_manual',{id,matriculaId});await carregar()}catch(e){alert(e.message)}}
async function salvarMotivo(id,matriculaId){try{await post('atualizar_motivo_cancelamento_sponte',{id,matriculaId,motivo:document.getElementById(`mot-${id||('m'+matriculaId)}`).value});await carregar()}catch(e){alert(e.message)}}
carregar();
</script></body></html>
